scene.background = new THREE.Color('#10141f');
camera.position.set(4, 3, 6);
controls.target.set(0, 0, 0);

// A soft studio light and a directional key light.
scene.add(new THREE.HemisphereLight('#cbdcff', '#45415d', 2));
const light = new THREE.DirectionalLight('#ffffff', 3);
light.position.set(3, 5, 4);
scene.add(light);

const grid = new THREE.GridHelper(14, 28, '#30374d', '#202738');
grid.position.y = -1.05;
scene.add(grid);

const count = 800;
const positions = new Float32Array(count * 3);
for (let i = 0; i < count; i++) {
  const angle = i * 2.39996;
  const radius = Math.sqrt(i / count) * 3;
  positions[i * 3] = Math.cos(angle) * radius;
  positions[i * 3 + 1] = Math.sin(i * 0.37) * 0.7;
  positions[i * 3 + 2] = Math.sin(angle) * radius;
}
const geometry = new THREE.BufferGeometry();
geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
const material = new THREE.PointsMaterial({ color: '#c8b1ff', size: 0.02 });
const points = new THREE.Points(geometry, material);
scene.add(points);
onFrame(({ delta }) => { points.rotation.y += delta * 0.15; });

material.size = 0.02;

