scene.background = new THREE.Color('#10141f');
camera.position.set(4, 3, 6);
controls.target.set(0, 0, 0);

// A soft studio light and a directional key light.
scene.add(new THREE.HemisphereLight('#cbdcff', '#45415d', 2));
const light = new THREE.DirectionalLight('#ffffff', 3);
light.position.set(3, 5, 4);
scene.add(light);

const grid = new THREE.GridHelper(14, 28, '#30374d', '#202738');
grid.position.y = -1.05;
scene.add(grid);

const count = 12;
const geometry = new THREE.BoxGeometry(0.18, 0.6, 0.18);
const material = new THREE.MeshStandardMaterial({ color: '#b49aff' });
const instances = new THREE.InstancedMesh(geometry, material, count);
const transform = new THREE.Object3D();
for (let i = 0; i < count; i++) {
  const angle = i / count * Math.PI * 2;
  transform.position.set(Math.cos(angle) * 2, Math.sin(angle * 3) * 0.4, Math.sin(angle) * 2);
  transform.rotation.y = -angle;
  transform.updateMatrix();
  instances.setMatrixAt(i, transform.matrix);
}
instances.instanceMatrix.needsUpdate = true;
scene.add(instances);

