scene.background = new THREE.Color('#10141f');
camera.position.set(4, 3, 6);
controls.target.set(0, 0, 0);

// A soft studio light and a directional key light.
scene.add(new THREE.HemisphereLight('#cbdcff', '#45415d', 2));
const light = new THREE.DirectionalLight('#ffffff', 3);
light.position.set(3, 5, 4);
scene.add(light);

const grid = new THREE.GridHelper(14, 28, '#30374d', '#202738');
grid.position.y = -1.05;
scene.add(grid);

const geometry = new THREE.PlaneGeometry(3, 3, 48, 48);
const material = new THREE.ShaderMaterial({
  side: THREE.DoubleSide,
  uniforms: { uTime: { value: 0 }, uAmplitude: { value: 0 }, uMix: { value: 0 } },
  vertexShader: `
    uniform float uTime;
    uniform float uAmplitude;
    varying vec2 vUv;
    void main() {
      vUv = uv;
      vec3 p = position;
      p.z += sin(p.x * 4.0 + uTime) * uAmplitude;
      gl_Position = projectionMatrix * modelViewMatrix * vec4(p, 1.0);
    }
  `,
  fragmentShader: `
    uniform float uMix;
    varying vec2 vUv;
    void main() {
      vec3 purple = vec3(0.55, 0.32, 0.9);
      vec3 mint = vec3(0.3, 0.9, 0.65);
      vec3 color = mix(purple, mint, vUv.x * uMix);
      gl_FragColor = vec4(color, 1.0);
      #include <tonemapping_fragment>
      #include <colorspace_fragment>
    }
  `
});
const mesh = new THREE.Mesh(geometry, material);
scene.add(mesh);
onFrame(({ elapsed }) => { material.uniforms.uTime.value = elapsed; });

material.uniforms.uAmplitude.value = 0;

